def fill_company_and_deactivate_duplicates(apps, schema_editor):
    connection = schema_editor.connection
    if connection.vendor == 'postgresql':
        # FK checks fire now, not at commit, so the later CREATE INDEX on the same table does not hit
        # "pending trigger events".
        schema_editor.execute('SET CONSTRAINTS ALL IMMEDIATE')
    PettyCashAccount = apps.get_model('personnel', 'PettyCashAccount')
    filled = 0
    for acc in (PettyCashAccount.objects.filter(company__isnull=True, section__isnull=False)
                .select_related('section__project').order_by('id')):
        PettyCashAccount.objects.filter(pk=acc.pk).update(company_id=acc.section.project.company_id)
        filled += 1
    PettyCashTransaction = apps.get_model('personnel', 'PettyCashTransaction')
    kept = {}
    deactivated = 0
    moved = 0
    for acc in PettyCashAccount.objects.filter(is_active=True, company__isnull=False).order_by('id'):
        key = (acc.company_id, acc.custodian_id)
        if key in kept:
            # The duplicate is only deactivated; its rows move to the kept account (each row keeps its section)
            # so balance, open expenses and debt stay visible. Nothing is deleted.
            moved += PettyCashTransaction.objects.filter(account_id=acc.pk).update(account_id=kept[key])
            PettyCashAccount.objects.filter(pk=acc.pk).update(is_active=False)
            deactivated += 1
            print(f"\n  petty cash account {acc.pk} deactivated, its rows moved to account {kept[key]}")
        else:
            kept[key] = acc.pk
    if connection.vendor == 'postgresql':
        schema_editor.execute('SET CONSTRAINTS ALL DEFERRED')
    print(f"\n  petty cash accounts: company filled on {filled}, "
          f"duplicate active accounts deactivated: {deactivated}, rows moved: {moved}")


